const base = String($env.GMAIL_BASE ?? '').trim().toLowerCase();
if (!/^[a-z0-9.]+$/.test(base)) {
  throw new Error('GMAIL_BASE must be set to a Gmail username; emails are never sent to addresses from the CSV.');
}

const escape = (value) =>
  String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const rupees = (value) => `₹${Number(value).toLocaleString('en-IN')}`;
const amount = (value) => (value >= 100000 ? `₹${(value / 100000).toLocaleString('en-IN')} lakh` : rupees(value));

const user = $json;
const firstName = String(user.name ?? '').trim().split(/\s+/)[0] || 'there';
const alias = `${firstName.toLowerCase().replace(/[^a-z0-9]/g, '') || 'user'}-${user.user_id.slice(0, 4)}`;
const toAddress = `${base}+${alias}@gmail.com`;
const products = user.products;

const facts = (product) =>
  [
    product.interest_rate_min ? `from ${product.interest_rate_min}% p.a.` : null,
    product.max_amount ? `up to ${amount(product.max_amount)}` : null,
    product.verdict === 'eligible' ? 'Strong fit' : 'Likely fit',
  ]
    .filter(Boolean)
    .join(' · ');

const card = (product, index) => `
  <tr><td style="padding:0 0 12px">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e4e7ec;border-radius:12px">
      <tr><td style="padding:16px 20px">
        <div style="font:600 12px/16px system-ui,sans-serif;color:#667085;letter-spacing:.04em;text-transform:uppercase">${index + 1} · ${escape(product.lender)}</div>
        <div style="font:600 16px/24px system-ui,sans-serif;color:#101828;margin-top:2px">${escape(product.product_name)}</div>
        <div style="font:500 13px/20px system-ui,sans-serif;color:#027a48;margin-top:4px">${escape(facts(product))}</div>
        <div style="font:400 13px/20px system-ui,sans-serif;color:#475467;margin-top:8px">${escape(product.reason)}</div>
        <a href="${escape(product.source_url)}" style="display:inline-block;margin-top:12px;font:600 13px/20px system-ui,sans-serif;color:#1d4ed8;text-decoration:none">View eligibility details →</a>
      </td></tr>
    </table>
  </td></tr>`;

const subject = `${firstName}, ${products.length} personal loan${products.length > 1 ? 's' : ''} match your profile`;

const html = `<!doctype html><html><body style="margin:0;background:#f5f6f8">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f5f6f8"><tr><td align="center" style="padding:32px 16px">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:16px">
    <tr><td style="padding:28px 28px 8px">
      <div style="font:600 13px/20px system-ui,sans-serif;color:#1d4ed8">Loan Match</div>
      <h1 style="font:700 22px/30px system-ui,sans-serif;color:#101828;margin:8px 0 0">Hi ${escape(firstName)}, these loans fit your profile</h1>
      <p style="font:400 14px/22px system-ui,sans-serif;color:#475467;margin:8px 0 0">Matched on a monthly income of ${rupees(user.monthly_income)} and a CIBIL score of ${user.credit_score}. Best fit first.</p>
    </td></tr>
    <tr><td style="padding:16px 28px 8px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">${products.map(card).join('')}</table></td></tr>
    <tr><td style="padding:8px 28px 28px;font:400 12px/18px system-ui,sans-serif;color:#98a2b3">
      Lenders make the final credit decision. Rates and limits are taken from each lender's public eligibility page.<br>
      Demo delivery: this email was addressed to ${escape(user.email)} in the uploaded file and redirected to a test inbox.
    </td></tr>
  </table>
</td></tr></table>
</body></html>`;

const text = [
  `Hi ${firstName}, these loans fit your profile.`,
  `Matched on a monthly income of ${rupees(user.monthly_income)} and a CIBIL score of ${user.credit_score}.`,
  '',
  ...products.map((product, index) => `${index + 1}. ${product.lender}: ${product.product_name}\n   ${facts(product)}\n   ${product.reason}\n   ${product.source_url}`),
  '',
  `Demo delivery: originally addressed to ${user.email}.`,
].join('\n');

return {
  json: {
    batch_id: $('Start notifying').first().json.batch_id,
    user_id: user.user_id,
    to_address: toAddress,
    product_ids: products.map((product) => product.product_id),
    message: {
      FromEmailAddress: $env.SES_FROM,
      Destination: { ToAddresses: [toAddress] },
      Content: {
        Simple: {
          Subject: { Data: subject, Charset: 'UTF-8' },
          Body: { Html: { Data: html, Charset: 'UTF-8' }, Text: { Data: text, Charset: 'UTF-8' } },
        },
      },
    },
  },
};
